"""Portable experiment artifacts and a dependency-free interactive HTML report."""
from __future__ import annotations

import json
from pathlib import Path

import numpy as np


def serializable(value):
    if isinstance(value, np.ndarray):
        return serializable(value.tolist())
    if isinstance(value, np.generic):
        return serializable(value.item())
    if isinstance(value, dict):
        return {str(k): serializable(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [serializable(v) for v in value]
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, float) and not np.isfinite(value):
        return None
    return value


def write_json(path: Path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(serializable(value), ensure_ascii=False, indent=2, allow_nan=False), encoding="utf-8")


def export_trace(path: Path, result: dict):
    import csv
    keys = ["s_m", "x_m", "y_m", "speed_mps", "time_s", "mguk_dc_kw", "energy_mj", "soc_fraction", "recharge_mj", "ax_mps2", "ay_mps2", "requested_actions", "executed_actions", "aero_mode"]
    columns = {k: np.asarray(result[k]) for k in keys if k in result and np.ndim(result[k]) == 1}
    n = len(result["speed_mps"])
    with path.open("w", newline="", encoding="utf-8-sig") as handle:
        writer = csv.writer(handle)
        writer.writerow(columns)
        writer.writerows([[v[i] for v in columns.values()] for i in range(n)])


def render_report(output_path: Path, bundle: dict):
    payload = json.dumps(serializable(bundle), ensure_ascii=False, allow_nan=False).replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    output_path.write_text(TEMPLATE.replace("__DATA__", payload), encoding="utf-8")


